def calculate_A(B):
    """Calculates A based on B for the equation 328 AB = 7A + 7B + 7."""
    # A = (7B + 7) / (328B - 7)
    numerator = 7 * B + 7
    denominator = 328 * B - 7
    if denominator <= 0:
        return None # Should not happen for B >= 1
    return numerator / denominator

# Check for integer A for small positive integers B
print("Checking for integer A for B=1 to 10:")
results = {}
for B in range(1, 11):
    A = calculate_A(B)
    if A is not None:
        results[B] = A
        if A == int(A):
            print(f"Found integer solution (A, B) = ({int(A)}, {B}) for B={B}")

print("\nDetailed results:")
for B, A in results.items():
    print(f"B={B}: A = {A}")

